/**
 * Material Symbols Rounded vector icons for Folio UI chrome (Bottom Navigation,
 * Settings cards, Status Banner, and Period/Screen headers).
 */
object FolioChromeIcons {

    private fun symbol(
        name: String,
        pathData: String,
        autoMirror: Boolean = false
    ): ImageVector {
        return ImageVector.Builder(
            name = "MaterialSymbolsRounded.$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 960f,
            viewportHeight = 960f,
            autoMirror = autoMirror
        ).group(translationY = 960f) {
            addPath(
                pathData = addPathNodes(pathData),
                fill = SolidColor(Color.Black)
            )
        }.build()
    }

